162	/**
163	 * Lists (or searches) knowledge insights stored in the ledger's `.knowledge/` directory.
164	 *
165	 * - When `query` is present, delegates to `KnowledgeStoreManager.searchInsights()`.
166	 * - Otherwise calls `KnowledgeStoreManager.listInsights()` with scope/category/tags filters.
167	 * - `scope` is validated via `InsightScope.safeParse()`; unrecognised values throw
168	 *   `VALIDATION_ERROR`. Omitting `scope` (or passing `undefined`) returns all insights.
169	 * - `tags` is a comma-separated string that is split before being forwarded.
170	 * - `limit` and `offset` are coerced to non-negative integers; invalid/missing values
171	 *   are silently ignored (limit → undefined, offset → 0).
172	 * - `limit=0` is treated as unlimited (mapped to undefined); pass a positive integer
173	 *   to enforce a page size.
174	 */
175	export async function handleListKnowledge(
176	  ledgerRoot: string,
177	  params: KnowledgeListParams = {}
178	): Promise<Insight[]> {
179	  const manager = new KnowledgeStoreManager(ledgerRoot);
180	
181	  // Validate scope — reject any non-nullish string that is not a valid InsightScope value.
182	  // Absent scope (undefined) means "no filter" and is always allowed.
183	  let scope: 'global' | 'repository' | undefined;
184	  if (params.scope !== undefined) {
185	    const scopeResult = InsightScope.safeParse(params.scope);
186	    if (!scopeResult.success) {
187	      validationError(`Invalid scope value: '${params.scope}'. Must be 'global' or 'repository'.`);
188	    }
189	    scope = scopeResult.data;
190	  }
191	
192	  const category = params.category ?? undefined;
193	  const repository_name = params.repository_name ?? undefined;
194	
195	  // Split comma-separated tags; ignore empty segments.
196	  const tags =
197	    params.tags && params.tags.trim().length > 0
198	      ? params.tags
199	          .split(',')
200	          .map((t) => t.trim())
201	          .filter((t) => t.length > 0)
202	      : undefined;
203	
204	  // Coerce pagination params.
205	  const limitRaw = params.limit !== undefined ? Math.floor(Number(params.limit)) : NaN;
206	  const limit = !isNaN(limitRaw) && limitRaw > 0 ? limitRaw : undefined;
207	
208	  const offsetRaw = params.offset !== undefined ? Math.floor(Number(params.offset)) : NaN;
209	  const offset = !isNaN(offsetRaw) && offsetRaw >= 0 ? offsetRaw : 0;
210	
211	  if (params.query && params.query.trim().length > 0) {
212	    return manager.searchInsights(params.query.trim(), { scope, repository_name, category, tags, limit, offset });
213	  }
214	
215	  return manager.listInsights({ scope, category, tags, repository_name, limit, offset });
216	}
