222	/**
223	 * Updates an existing knowledge insight identified by its numeric ID.
224	 *
225	 * Validates the raw ID string via `parseKnowledgeId` (throws VALIDATION_ERROR
226	 * for non-integer, zero, or floating-point strings). Validates the request body
227	 * via `KnowledgeUpdateBodySchema` (throws VALIDATION_ERROR for unknown fields or
228	 * type mismatches). Extracts `scope` and `repository_name` discriminator fields to
229	 * scope the update to the correct store.
230	 *

231	 * `superseded_by: null` in the body is mapped to `undefined` so the field is
232	 * cleared (removed) on the stored insight.
233	 *
234	 * Throws NOT_FOUND when no insight with the given ID exists in the specified scope.
235	 *
236	 * @param ledgerRoot  Absolute path to the central ledger root.
237	 * @param rawId       Raw ID string from the URL parameter (e.g. "42").
238	 * @param body        Parsed request body (any shape — validated here).
239	 * @returns The updated Insight.
240	 */
241	export async function handleUpdateKnowledge(
242	  ledgerRoot: string,
243	  rawId: string,
244	  body: unknown
245	): Promise<Insight> {
246	  const id = parseKnowledgeId(rawId);
247	
248	  const parseResult = KnowledgeUpdateBodySchema.safeParse(body);
249	  if (!parseResult.success) {
250	    validationError('Invalid knowledge update body.', parseResult.error.issues);
251	  }
252	
253	  const { scope, repository_name, superseded_by, ...rest } = parseResult.data;
254	
255	  // Map superseded_by: null → undefined so the field is cleared on the stored insight.
256	  const updates: Parameters<KnowledgeStoreManager['updateInsight']>[1] = {
257	    ...rest,
258	    ...(superseded_by === null ? { superseded_by: undefined } : superseded_by !== undefined ? { superseded_by } : {}),
259	  };
260	
261	  const manager = new KnowledgeStoreManager(ledgerRoot);
262	
263	  try {
264	    return await manager.updateInsight(id, updates, { scope, repository_name });
265	  } catch (err) {
266	    const msg = err instanceof Error ? err.message : String(err);
267	    if (msg.includes('not found')) {
268	      throw new ApiError('NOT_FOUND', 'Insight not found.');
269	    }
270	    throw err;
271	  }
272	}
